#include <stdio.h>
#include <string.h>

int main(void) {
    char bowl[32] = "{w}";
    char other[32] = "{w}";

    printf("这两串一样吗？%s\n", strcmp(bowl, other) == 0 ? "一样" : "不一样");
    return 0;
}
